// ── PROMPT BUILDER ──
// Takes merged trend data and builds the God-Level script prompt

const trendData = $input.all();

// Extract trend topics
let topics = [];
try {
  // From Google Trends RSS
  const rss = trendData[0]?.json?.data || '';
  const matches = rss.match(/<title>([^<]+)<\/title>/g) || [];
  topics = matches.slice(1, 6).map(m => m.replace(/<\/?title>/g, ''));
} catch(e) {}

try {
  // From Reddit
  const posts = trendData[1]?.json?.data?.children || [];
  posts.slice(0, 5).forEach(p => {
    topics.push(p.data?.title || '');
  });
} catch(e) {}

const topicsStr = topics.join(', ');

// ── Build the God-Level Script Prompt ──
const niche = 'psychology'; // Change to your channel niche
const niches = {
  psychology: {
    tone: 'analytical, slightly ominous, authoritative',
    audience: '18-35, curious about human behavior',
    hookStyle: 'myth-busting behavioral claims',
    hooks: [
      'If someone {topic}, they\'re not what you think...',
      'You\'ve been reading this body language wrong your whole life...',
    ]
  },
  data_storytelling: {
    tone: 'journalistic, surprising, data-driven',
    audience: '20-40, data enthusiasts, visual learners',
    hookStyle: 'counter-intuitive data reveal',
    hooks: [
      'Everyone thinks {topic}... the data says the opposite.',
      'This one number just changed everything about {topic}...',
    ]
  }
};

const profile = niches[niche] || niches.psychology;

const prompt = `You are an elite viral scriptwriter for YouTube Shorts in the '${niche}' niche.

Trending topics today: ${topicsStr}

Pick the most interesting topic and create a 45-60 second viral script.
Target Audience: ${profile.audience}
Tone: ${profile.tone}

Constraint 1 — SHOCK HOOK (first 3 seconds):
The opening MUST debunk a common belief or make an impossible-sounding claim.
Do NOT use: "Did you know", "In this video", "Hey guys"

Constraint 2 — LOOPING LOGIC:
The final sentence must lead back into the first.

Constraint 3 — WORD LIMIT:
Total script must be 40-80 words.

Constraint 4 — SAECS Framework:
S(hock) → A(mplify) → E(vidence) → C(onclusion) → S(ubscribe CTA)

Output Format: Return ONLY valid JSON:
{
  "hook": "first 1-2 sentences",
  "body": "middle section",
  "conclusion": "the insight",
  "cta": "subscribe call-to-action",
  "full_script": "complete script as one paragraph",
  "word_count": 65,
  "search_queries": ["query1", "query2", "query3"],
  "pin_comment": "engagement question",
  "title": "YouTube title under 70 chars with emoji"
}

Do NOT include any text outside the JSON.`;

// Determine AI endpoint
let aiUrl = 'http://localhost:11434/api/generate';
const groqKey = '';

if (groqKey) {
  aiUrl = 'https://api.groq.com/openai/v1/chat/completions';
}

return [{
  json: {
    architect_prompt: prompt,
    ai_url: aiUrl,
    groq_key: groqKey,
    niche: niche,
    trends: topicsStr,
    attempt: 1,
    max_attempts: 3
  }
}];

// ── PARSE AI RESPONSE ──
// Extract the script JSON from Ollama/Groq response

const input = $input.first().json;
let scriptData = {};

try {
  // Ollama format
  if (input.response) {
    scriptData = typeof input.response === 'string' 
      ? JSON.parse(input.response) 
      : input.response;
  }
  // Groq format  
  else if (input.choices) {
    const content = input.choices[0].message.content;
    scriptData = JSON.parse(content);
  }
  // Direct JSON
  else {
    scriptData = input;
  }
} catch(e) {
  // Try to extract JSON from mixed text
  const text = JSON.stringify(input);
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    scriptData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Could not parse AI response as JSON');
  }
}

// Validate required fields
const required = ['full_script', 'title', 'search_queries'];
for (const field of required) {
  if (!scriptData[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// Pass through attempt info
scriptData.attempt = input.attempt || 1;
scriptData.max_attempts = input.max_attempts || 3;
scriptData.niche = input.niche || 'psychology';

return [{ json: scriptData }];

// ══════════════════════════════════════════════════════
// 🔍 GOD-LEVEL VALIDATION NODE
// ══════════════════════════════════════════════════════
// This is the AI Judge. It scores scripts on 5 dimensions
// and returns APPROVE/REJECT with actionable feedback.
// ══════════════════════════════════════════════════════

const script = $input.first().json;
const attempt = script.attempt || 1;
const maxAttempts = script.max_attempts || 3;

// ── Niche Profiles ──
const profiles = {
  psychology: {
    name: 'Dark Psychology & Body Language',
    audience: '18-35, curious about human behavior',
  },
  data_storytelling: {
    name: 'Data Storytelling & Visual Economics',
    audience: '20-40, data enthusiasts',
  }
};
const profile = profiles[script.niche] || profiles.psychology;

// ── Build Validation Prompt ──
const validationPrompt = `You are an elite YouTube Shorts quality control AI. Judge whether this script is good enough to produce.

Channel Niche: ${profile.name}
Target Audience: ${profile.audience}
Title: ${script.title || 'Unknown'}
Attempt: ${attempt} of ${maxAttempts}

Script to evaluate:
"""${script.full_script}"""

Score each dimension from 1-10:

1. Hook Strength (weight: 30%) — Do the first 1-2 sentences stop the scroll?
   9-10: Impossible to scroll past. Counter-intuitive, myth-busting.
   7-8: Strong curiosity trigger.
   5-6: Generic "Did you know" territory.
   1-4: Viewer scrolls immediately.

2. Factual Accuracy (weight: 25%) — Are claims verifiable?
   9-10: Backed by research.
   7-8: Plausible and commonly cited.
   5-6: Oversimplifications.
   1-4: Fabricated or dangerous.

3. Boredom Score (weight: 20%) — Overall engagement.
   9-10: Every sentence adds tension. Zero filler.
   7-8: Engaging with minor slow spots.
   5-6: Middle drags.
   1-4: Wikipedia article.

4. Loop Potential (weight: 15%) — Does ending connect to beginning?
   9-10: Seamless loop.
   7-8: References opening theme.
   5-6: Fine but no loop.
   1-4: Abrupt.

5. CTA Clarity (weight: 10%) — Natural call-to-action?
   9-10: Part of the story.
   7-8: Clear without breaking immersion.
   5-6: Forced but acceptable.
   1-4: Cringe.

Decision:
- APPROVE if: weighted avg >= 7.0 AND hook >= 7, accuracy >= 8, boredom >= 7, loop >= 6, cta >= 5
- REJECT otherwise

Return ONLY valid JSON:
{
  "verdict": "APPROVE or REJECT",
  "overall_score": 7.5,
  "scores": {
    "hook_strength": 8,
    "factual_accuracy": 9,
    "boredom_score": 7,
    "loop_potential": 7,
    "cta_clarity": 8
  },
  "weighted_average": 7.9,
  "rejection_reason": "only if REJECT",
  "rewrite_instructions": "only if REJECT",
  "praise": "what works well",
  "attempt": ${attempt},
  "max_retries_remaining": ${maxAttempts - attempt}
}`;

return [{
  json: {
    ...script,
    validation_prompt: validationPrompt,
    ai_url: 'http://localhost:11434/api/generate'
  }
}];

// ── PARSE VALIDATION RESULT ──

const input = $input.first().json;
let validation = {};

try {
  if (input.response) {
    validation = typeof input.response === 'string'
      ? JSON.parse(input.response)
      : input.response;
  } else if (input.choices) {
    validation = JSON.parse(input.choices[0].message.content);
  } else {
    validation = input;
  }
} catch(e) {
  const text = JSON.stringify(input);
  const match = text.match(/\{[\s\S]*\}/);
  if (match) validation = JSON.parse(match[0]);
  else {
    // If parsing fails, auto-approve to not block pipeline
    validation = { verdict: 'APPROVE', overall_score: 7, parse_error: true };
  }
}

// Carry forward the script data
const prevData = $('📝 Parse Script').first().json;

return [{
  json: {
    ...prevData,
    validation: validation,
    verdict: (validation.verdict || 'APPROVE').toUpperCase(),
    validation_score: validation.weighted_average || validation.overall_score || 0
  }
}];

// ── REJECTION HANDLER ──
// Check retry count, either loop back or skip topic

const data = $input.first().json;
const attempt = (data.attempt || 1) + 1;
const maxAttempts = data.max_attempts || 3;
const validation = data.validation || {};

if (attempt > maxAttempts) {
  // Max retries exceeded — skip this topic
  return [{
    json: {
      action: 'SKIP',
      reason: `Script failed validation ${maxAttempts} times. Last rejection: ${validation.rejection_reason || 'Unknown'}`,
      last_score: data.validation_score,
      topic: data.title,
      timestamp: new Date().toISOString()
    }
  }];
}

// Build retry prompt with rejection feedback
const retryPrompt = `You are an elite viral scriptwriter. Your previous script was REJECTED by quality control.

REJECTION REASON: ${validation.rejection_reason || 'Script did not meet quality standards'}
REWRITE INSTRUCTIONS: ${validation.rewrite_instructions || 'Improve the hook and reduce filler words'}
WHAT WORKED: ${validation.praise || 'Topic choice was good'}

This is attempt ${attempt} of ${maxAttempts}. 

Original script that was rejected:
"""${data.full_script}"""

Rewrite this script following the rejection feedback.
Keep the same topic but make it significantly better.

Constraints:
- 40-80 words max
- Hook must stop the scroll in 3 seconds
- Use SAECS framework: Shock → Amplify → Evidence → Conclusion → Subscribe
- Ending must loop back to beginning

Return ONLY valid JSON:
{
  "hook": "scroll-stopping opener",
  "body": "middle section",
  "conclusion": "insight payoff",
  "cta": "natural subscribe CTA",
  "full_script": "complete rewritten script",
  "word_count": 65,
  "search_queries": ["query1", "query2", "query3"],
  "pin_comment": "engagement question",
  "title": "${data.title || 'Rewritten title with emoji'}"
}`;

return [{
  json: {
    architect_prompt: retryPrompt,
    ai_url: 'http://localhost:11434/api/generate',
    niche: data.niche || 'psychology',
    attempt: attempt,
    max_attempts: maxAttempts,
    previous_rejection: validation.rejection_reason
  }
}];

// ── LOG SKIP ──
const data = $input.first().json;
console.log(`⏭️ SKIPPED: ${data.topic} — ${data.reason}`);
return [{ json: { ...data, logged: true } }];

// ══════════════════════════════════════════════
// 🎬 APPROVED — Prepare for Video Production
// ══════════════════════════════════════════════

const data = $input.first().json;

// Build the production manifest
const manifest = {
  // Script data
  title: data.title || `Untitled Short`,
  full_script: data.full_script,
  hook: data.hook,
  body: data.body,
  conclusion: data.conclusion,
  cta: data.cta,
  word_count: data.word_count,

  // Search queries for Pexels footage
  search_queries: data.search_queries || ['dark portrait', 'person dark room', 'moody face'],

  // YouTube metadata
  pin_comment: data.pin_comment || 'What do you think? 👀',
  tags: ['psychology', 'dark psychology', 'body language', 'shorts', 'facts'],
  category_id: '27',

  // Validation results
  validation_score: data.validation_score,
  validation_attempt: data.attempt || 1,
  verdict: data.verdict,

  // Pipeline control
  timestamp: new Date().toISOString(),
  status: 'APPROVED_FOR_PRODUCTION'
};

// Generate description
manifest.description = [
  manifest.full_script,
  '',
  '👆 Double tap if you agree',
  '🔔 SUBSCRIBE for daily dark psychology facts',
  '',
  '#Shorts #DarkPsychology #BodyLanguage #PsychologyFacts',
  '#ManipulationTactics #ReadPeople #HumanBehavior',
].join('\n');

return [{ json: manifest }];

// ── FINAL LOG ──
const data = $input.first().json;
const summary = {
  status: 'COMPLETE',
  title: data.title,
  validation_score: data.validation_score,
  timestamp: new Date().toISOString(),
  output: data.stdout || 'Pipeline executed'
};
console.log(JSON.stringify(summary, null, 2));
return [{ json: summary }];
